describe('Skip to Content Link Accessibility', () => {
  beforeEach(() => {
    cy.visit('/accessibility-test');
  });

  it('should display skip to content link and navigate to main content', () => {
    // Verify skip to content link is visible
    cy.get('[data-testid="skip-to-content"]').should('be.visible');
    cy.get('[data-testid="skip-to-content"]').should('contain', 'Skip to main content');

    // Verify link has correct href
    cy.get('[data-testid="skip-to-content"]').should('have.attr', 'href', '#main-content');

    // Click the skip to content link
    cy.get('[data-testid="skip-to-content"]').click();

    // Verify page scrolls to main content section
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.window().then((win) => {
      expect(win.scrollY).to.be.greaterThan(0);
    });

    // Verify main content is now in viewport
    cy.get('[data-testid="main-content"]').should('be.visible');
  });

  it('should hide skip to content link after first click and maintain focus', () => {
    // Verify skip to content link is visible before first click
    cy.get('[data-testid="skip-to-content"]').should('be.visible');

    // Click the skip to content link
    cy.get('[data-testid="skip-to-content"]').click();

    // Verify skip to content link is hidden after first click
    cy.get('[data-testid="skip-to-content"]').should('not.exist');

    // Verify main content is still accessible and visible
    cy.get('[data-testid="main-content"]').should('be.visible');

    // Verify focus is on main content
    cy.get('[data-testid="main-content"]').should('have.focus');

    // Verify skip to content link does not reappear on subsequent clicks
    cy.get('[data-testid="skip-to-content"]').should('not.exist');
  });
});
